import React from 'react';

const LOGO_SRC = "data:image/png;base64,";

interface CELogoProps {
  size?: number;
}

export const CELogo: React.FC<CELogoProps> = ({ size = 48 }) => {
  return (
    <img
      src={LOGO_SRC}
      alt="Click Express Inc"
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        borderRadius: "50%",
        background: "#fff",
        display: "block",
        padding: size > 60 ? 6 : 3,
      }}
    />
  );
};